import {
  Body,
  Container,
  Head,
  Html,
  Preview,
  Section,
  Text,
} from "@react-email/components";
import type { DealsByOrigin, ScoredDeal } from "@/lib/deals/scoreAndFilter";

type Props = {
  deals: DealsByOrigin;
  generatedAt: string;
};

function isEuropeContinent(label: string): boolean {
  return label.trim().toLowerCase() === "europe";
}

function selectTopDealsToday(allDeals: ScoredDeal[]): ScoredDeal[] {
  return [...allDeals]
    .filter((d) => d.hubFare.stops === 0 && d.scoreResult.score >= 75)
    .sort((a, b) => a.hubFare.price - b.hubFare.price)
    .slice(0, 5);
}

function selectIntraEuropeTop(allDeals: ScoredDeal[]): ScoredDeal[] {
  return [...allDeals]
    .filter(
      (d) =>
        isEuropeContinent(d.hubFare.hub.originContinent) &&
        isEuropeContinent(d.hubFare.destinationContinent)
    )
    .sort((a, b) => a.hubFare.price - b.hubFare.price)
    .slice(0, 10);
}

function selectOutsideEuropeTop(allDeals: ScoredDeal[]): ScoredDeal[] {
  return [...allDeals]
    .filter(
      (d) =>
        isEuropeContinent(d.hubFare.hub.originContinent) &&
        d.hubFare.destinationContinent.trim() !== "" &&
        !isEuropeContinent(d.hubFare.destinationContinent)
    )
    .sort((a, b) => a.hubFare.price - b.hubFare.price)
    .slice(0, 10);
}

function DigestDealCard({
  deal,
  index,
}: {
  deal: ScoredDeal;
  index: number;
}) {
  return (
    <Section
      style={{
        borderLeft: "3px solid #4ade80",
        paddingLeft: "12px",
        marginTop: index === 0 ? "0" : "14px",
      }}
    >
      <Text
        style={{
          margin: "0 0 6px 0",
          color: "#ffffff",
          fontSize: "24px",
          fontWeight: "700",
        }}
      >
        {`${deal.hubFare.hub.originCity} → ${deal.hubFare.destinationCity} — $${Math.round(deal.hubFare.price)}`}
      </Text>
      <Text
        style={{
          margin: "0 0 4px 0",
          color: "#888",
          fontSize: "12px",
          letterSpacing: "0.02em",
        }}
      >
        Airport codes {deal.hubFare.hub.origin} → {deal.hubFare.destination}
      </Text>
      <Text
        style={{
          margin: "0 0 8px 0",
          color: "#aaa",
          fontSize: "14px",
        }}
      >
        {deal.hubFare.airline}
      </Text>
      <Text
        style={{
          margin: "0 0 10px 0",
          color: "#aaa",
          fontSize: "13px",
        }}
      >
        {deal.hubFare.departureDate} to {deal.hubFare.returnDate}
      </Text>
      <Text style={{ margin: "0 0 8px 0", lineHeight: "1.5" }}>
        <span
          style={{
            display: "inline-block",
            backgroundColor: "#1a1a1a",
            color: "#4ade80",
            padding: "4px 10px",
            borderRadius: "4px",
            fontSize: "12px",
          }}
        >
          Deal Score: {deal.scoreResult.score}/100
        </span>
        {deal.rssConfirmed ? (
          <span
            style={{
              display: "inline-block",
              marginLeft: "8px",
              padding: "2px 6px",
              fontSize: "9px",
              fontWeight: "600",
              letterSpacing: "0.02em",
              color: "#86efac",
              backgroundColor: "#1a1a1a",
              borderRadius: "3px",
              border: "1px solid #166534",
              verticalAlign: "middle",
            }}
          >
            ✓ Confirmed deal
          </span>
        ) : null}
      </Text>
      <Text
        style={{
          margin: "12px 0 0 0",
          color: "#e8e4dc",
          fontSize: "14px",
          fontStyle: "italic",
        }}
      >
        {deal.scoreResult.label}
      </Text>
    </Section>
  );
}

function HighlightSection({
  title,
  subtitle,
  deals,
  cardKeyPrefix,
}: {
  title: string;
  subtitle: string;
  deals: ScoredDeal[];
  cardKeyPrefix: string;
}) {
  if (deals.length === 0) return null;

  return (
    <Section
      style={{
        backgroundColor: "#111111",
        borderRadius: "8px",
        padding: "16px",
        margin: "0 0 24px 0",
      }}
    >
      <Text
        style={{
          margin: "0 0 8px 0",
          color: "#4ade80",
          fontSize: "24px",
          fontWeight: "700",
        }}
      >
        {title}
      </Text>
      <Text
        style={{
          margin: "0 0 16px 0",
          fontSize: "13px",
          color: "#888",
        }}
      >
        {subtitle}
      </Text>
      {deals.map((deal, index) => (
        <DigestDealCard
          key={`${cardKeyPrefix}-${deal.hubFare.hub.origin}-${deal.hubFare.destination}-${deal.hubFare.departureDate}-${index}`}
          deal={deal}
          index={index}
        />
      ))}
    </Section>
  );
}

export default function DealsDigest({ deals, generatedAt }: Props) {
  const flatDeals = Object.values(deals).flat();
  const topDealsToday = selectTopDealsToday(flatDeals);
  const intraEuropeDeals = selectIntraEuropeTop(flatDeals);
  const outsideEuropeDeals = selectOutsideEuropeTop(flatDeals);

  return (
    <Html>
      <Head />
      <Preview>Best Escapes This Week</Preview>
      <Body
        style={{
          backgroundColor: "#0a0a0a",
          margin: "0",
          padding: "40px",
          color: "#e8e4dc",
          fontFamily: "Arial, sans-serif",
        }}
      >
        <Container
          style={{
            maxWidth: "640px",
            margin: "0 auto",
            backgroundColor: "#0a0a0a",
          }}
        >
          <Text
            style={{
              margin: "0 0 8px 0",
              color: "#4ade80",
              fontSize: "28px",
              fontWeight: "700",
            }}
          >
            ✈ Best Escapes This Week
          </Text>
          <Text
            style={{
              margin: "0 0 24px 0",
              fontSize: "14px",
              color: "#888",
            }}
          >
            Surfaced automatically from major European hubs · {generatedAt}
          </Text>

          {topDealsToday.length > 0 ? (
            <Section
              style={{
                backgroundColor: "#111111",
                borderRadius: "8px",
                padding: "16px",
                margin: "0 0 24px 0",
              }}
            >
              <Text
                style={{
                  margin: "0 0 8px 0",
                  color: "#4ade80",
                  fontSize: "24px",
                  fontWeight: "700",
                }}
              >
                🔥 Top Deals Today
              </Text>
              <Text
                style={{
                  margin: "0 0 16px 0",
                  fontSize: "13px",
                  color: "#888",
                }}
              >
                Best nonstop fares across all European hubs right now
              </Text>

              {topDealsToday.map((deal, index) => (
                <DigestDealCard
                  key={`top-${deal.hubFare.hub.origin}-${deal.hubFare.destination}-${deal.hubFare.departureDate}-${index}`}
                  deal={deal}
                  index={index}
                />
              ))}
            </Section>
          ) : null}

          <Section style={{ margin: "8px 0 24px 0", borderTop: "1px solid #222" }} />

          <HighlightSection
            title="Within Europe"
            subtitle="Top 10 genuine deals flying between European hubs (by price)"
            deals={intraEuropeDeals}
            cardKeyPrefix="intra"
          />

          <HighlightSection
            title="Beyond Europe"
            subtitle="Top 10 genuine long-haul picks from European hubs (by price)"
            deals={outsideEuropeDeals}
            cardKeyPrefix="outside"
          />

          <Text
            style={{
              margin: "40px 0 0 0",
              fontSize: "12px",
              color: "#444",
            }}
          >
            Flight Deal Alerts · Built by Sam
          </Text>
        </Container>
      </Body>
    </Html>
  );
}
